// --------------------------------------------------------------------------
// Phenomena assets: the .dat layouts, the palette conversion and the table
// accessors.  Everything is generated by
// tools/private_tools/phenomena_assets.py from the vendored Go remake.
//
// The remake is 640x480.  The port works at 320x240 (one half in each axis) on
// a 400x280 overscan plane, so a 1x pixel is remake pixel (2x, 2y) exactly and
// nothing is resampled at runtime.
//
//   font.dat       45 glyphs of 16x26, u16 a row, bit x = ink
//   logo.dat       320x65 palette indices (0 = transparent)
//   photon.dat     35x8 mask, 0/1
//   bar_intro.dat  40 bytes: the opening grey raster, one 3-bit grey a row
//   bar_main.dat   12 rows of RGB: the purple frame raster
//   wave.dat       4096 (sin, cos) Q16.16 pairs over 2pi
// --------------------------------------------------------------------------
const std = @import("std");
const zg = @import("zigos");
const P = @import("palette.zig");

pub const PLANE: usize = 0;

/// The 320x240 content window, centred in the 400x280 overscan plane: 20 px
/// above and below (the remake is 4:3 and its canvas is 240 rows tall).
pub const CONTENT_X: usize = (zg.PHYSICAL_WIDTH - 320) / 2; // 40
pub const CONTENT_Y: usize = (zg.PHYSICAL_HEIGHT - 240) / 2; // 20
pub const CONTENT_W: usize = 320;
pub const CONTENT_H: usize = 240;

// --- palette indices -------------------------------------------------------
pub const IDX_BLACK: u8 = 0;
pub const IDX_BAR: u8 = 1; // rewritten per scanline by rasters.zig
pub const IDX_MIDDLE: u8 = 2; // #000111, the panel behind the DNA
pub const IDX_WHITE: u8 = 3;
pub const IDX_RED: u8 = 15; // the DNA core, or the photon on the photon's lines

pub const MIDDLE_RGB: [3]u8 = .{ 0, 0, 32 };

// --- font ------------------------------------------------------------------
pub const FONT_W: usize = 16;
pub const FONT_H: usize = 26;
pub const GLYPHS: usize = P.FONT_GLYPHS;

// --- logo ------------------------------------------------------------------
pub const LOGO_W: usize = P.LOGO_W;
pub const LOGO_H: usize = P.LOGO_H;
pub const LOGO_Y: usize = 0;

// --- photon ----------------------------------------------------------------
pub const PHOTON_W: usize = P.PHOTON_W;
pub const PHOTON_H: usize = P.PHOTON_H;
pub const PHOTON_X: usize = 142; // 285 / 2
pub const PHOTON_Y: usize = 222; // 445 / 2, the main scene's rest position

// --- bars ------------------------------------------------------------------
pub const BAR_INTRO_W: usize = 320;
pub const BAR_INTRO_H: usize = 40;
pub const BAR_TOP_Y: usize = 65; // content rows 65..70 (129..140 at 2x)
pub const BAR_BOTTOM_Y: usize = 215; // content rows 215..220 (430..440 at 2x)
pub const BAR_ROWS: usize = 6;

pub const font_bytes: []const u8 = @embedFile("../../assets/screens/phenomena/font.dat");
pub const logo: []const u8 = @embedFile("../../assets/screens/phenomena/logo.dat");
pub const photon: []const u8 = @embedFile("../../assets/screens/phenomena/photon.dat");
pub const bar_intro: []const u8 = @embedFile("../../assets/screens/phenomena/bar_intro.dat");
pub const bar_main: []const u8 = @embedFile("../../assets/screens/phenomena/bar_main.dat");
pub const wave_bytes: []const u8 = @embedFile("../../assets/screens/phenomena/wave.dat");

/// The ST palette writes a little-endian RGBA word (ikplus/assets.zig's rule).
pub inline fn rgb(r: u8, g: u8, b: u8) u32 {
    return 0xFF00_0000 | (@as(u32, b) << 16) | (@as(u32, g) << 8) | @as(u32, r);
}

pub inline fn rgb3(c: [3]u8) u32 {
    return rgb(c[0], c[1], c[2]);
}

pub inline fn paletteRGB(i: usize) u32 {
    return rgb3(P.RGB[i]);
}

/// font.dat row y of glyph g: 16 bits, bit x is ink.
pub inline fn glyphRow(g: u8, y: usize) u16 {
    const off = (@as(usize, g) * FONT_H + y) * 2;
    return std.mem.readInt(u16, font_bytes[off..][0..2], .little);
}

/// The opening raster's row d: a 3-bit grey (0..7).
pub inline fn introGrey(d: usize) u32 {
    const v: u8 = bar_intro[d] * 32;
    return rgb(v, v, v);
}

/// The purple frame raster's 2x row r (0..11).
pub inline fn mainBarRGB(r: usize) [3]u8 {
    return .{ bar_main[r * 3], bar_main[r * 3 + 1], bar_main[r * 3 + 2] };
}

pub const Wave = struct { sin: i32, cos: i32 };

pub inline fn wave(i: usize) Wave {
    const off = (i & 4095) * 8;
    return .{
        .sin = std.mem.readInt(i32, wave_bytes[off..][0..4], .little),
        .cos = std.mem.readInt(i32, wave_bytes[off + 4 ..][0..4], .little),
    };
}

comptime {
    std.debug.assert(CONTENT_X == 40 and CONTENT_Y == 20);
    std.debug.assert(font_bytes.len == GLYPHS * FONT_H * 2);
    std.debug.assert(logo.len == LOGO_W * LOGO_H);
    std.debug.assert(photon.len == PHOTON_W * PHOTON_H);
    std.debug.assert(bar_intro.len == BAR_INTRO_H);
    std.debug.assert(bar_main.len == 12 * 3);
    std.debug.assert(wave_bytes.len == 4096 * 8);
}
